def apply(t,put,ok):
    for tab,d in (('WeaponsJson',SPW),('AmmunitionsJson',SPA)):
        for k,f in d.items():
            ok(all(t[tab][int(k)].get(x)==ov[0] for x,ov in f.items()),f'{tab} {k} has the dev.12 values {f}')
            put(tab,int(k),{x:ov[1] for x,ov in f.items()})
            ok(all(t[tab][int(k)].get(x)==ov[1] for x,ov in f.items()),f'{tab} {k} now has the batch values')
    return {'source':'0.9.0-dev.12-hp5-burst-tier3-sam-claim6-gunsam','weapons':len(SPW),'rounds':len(SPA)}
